#!/usr/bin/env python3
"""Tunefield → Ableton Live Set (.als) exporter.

Turns a list of analysed tracks (or a Tunefield playlist, via the running
Flask app) into a Session-View Live Set that opens in ANY Live edition —
Intro, Lite, Standard, Suite — with no SDK, no beta, no extension:

  · two alternating deck tracks ("TF Deck A" / "TF Deck B"),
  · one scene per playlist step, named "01 · 126 BPM · 8A",
  · every clip warped to a constant grid at Tunefield's detected BPM
    (two warp markers — .als SecTime is seconds, verified empirically),
  · optional per-scene tempo so Live follows the set's tempo journey
    (something even the Extensions SDK cannot write),
  · files referenced in place, absolute path + relative fallback.

Pure stdlib. The generator does TEMPLATE SURGERY: it patches a stripped,
Live-12-written set (embedded below, regenerate with make_template.py)
rather than emitting XML from scratch, so every node Live expects is a
node Live itself wrote. Empirically verified invariants it maintains:
  · AutomationTarget/ModulationTarget Ids are globally unique pointees →
    renumbered per cloned track with ID_STRIDE; NextPointeeId > max.
  · ClipSlot Ids run 0..N-1 within each track; Scene Ids 0..N-1; every
    track's slot count equals the scene count.
  · WarpMarker/AudioClip/FileRef Ids are locally scoped (dup-safe).

Usage (standalone, against the running Tunefield):
    python3 als_export.py                        # active playlist → ./<name>.als
    python3 als_export.py --playlist my-set --out ~/Desktop/my-set.als
    python3 als_export.py --no-scene-tempo --tempo 126

Library:
    from als_export import AlsTrack, write_als
    write_als("set.als", [AlsTrack(path="/abs/a.mp3", bpm=126, ...)])
"""
from __future__ import annotations

import argparse
import base64
import copy
import gzip
import json
import math
import os
import re
import sys
import urllib.request
import xml.etree.ElementTree as ET
from dataclasses import dataclass

# Regenerate with make_template.py when a newer Live version's schema is needed.
_TEMPLATE_B64 = ""

ID_STRIDE = 100_000          # pointee-id offset per cloned track
_FALLBACK_BPM = 120.0
_SCENE_COLORS = [12, 20, 27, 36, 45, 54, 61, 3]   # Live colour indices, cycled
_RESOLVE_CHUNK = 500         # /tracks/resolve caps ids at 500 per request
# C0 control chars are ILLEGAL in XML 1.0 and ElementTree writes them raw,
# producing a file Live cannot parse (real-world source: ID3 null separators).
_CTRL_RE = re.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f]")


def _is_pointee(tag: str) -> bool:
    """Live's pointee-id space: AutomationTarget/ModulationTarget in ALL their
    variants (VolumeModulationTarget, ComplexProFormantsModulationTarget, …)
    plus bare Pointee nodes. Verified globally unique in every Live-written set."""
    return (tag == "Pointee"
            or tag.endswith("AutomationTarget")
            or tag.endswith("ModulationTarget"))


def _num_or_none(v, *, positive: bool = True) -> float | None:
    """Coerce JSON-ish numbers (int, float, numeric string); reject NaN/inf/<=0."""
    if v is None:
        return None
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(f) or (positive and f <= 0):
        return None
    return f


@dataclass
class AlsTrack:
    """One playlist entry. `path` must be absolute; everything else optional."""
    path: str
    title: str | None = None
    artist: str | None = None
    bpm: float | None = None
    key: str | None = None            # display string, e.g. "8A" or "C minor"
    duration_sec: float | None = None
    sample_rate_hz: int | None = None
    color: int | None = None          # Live colour index 0..69

    def __post_init__(self):
        # Normalise at the boundary: bridge/route input is JSON, where numbers
        # arrive stringly-typed and analyser NaNs survive the round trip.
        self.bpm = _num_or_none(self.bpm)
        self.duration_sec = _num_or_none(self.duration_sec)
        rate = _num_or_none(self.sample_rate_hz)
        self.sample_rate_hz = int(rate) if rate else None

    @property
    def display_name(self) -> str:
        name = " – ".join(x for x in (self.artist, self.title) if x)
        return name or os.path.splitext(os.path.basename(self.path))[0]


# --------------------------------------------------------------------------- #
#  XML helpers
# --------------------------------------------------------------------------- #

def _v(el: ET.Element, path: str, value) -> None:
    """Set the Value attribute of a child element, failing loudly if absent."""
    node = el.find(path)
    if node is None:
        raise KeyError(f"template node missing: {path}")
    if isinstance(value, str):
        value = _CTRL_RE.sub(" ", value)
    node.set("Value", str(value))


def _renumber_pointees(el: ET.Element, offset: int) -> int:
    """Offset every pointee Id under el; return the max id produced."""
    top = 0
    for node in el.iter():
        if _is_pointee(node.tag) and node.get("Id") is not None:
            new = int(node.get("Id")) + offset
            node.set("Id", str(new))
            top = max(top, new)
    return top


def _load_template() -> ET.Element:
    return ET.fromstring(gzip.decompress(base64.b64decode(_TEMPLATE_B64)))


# --------------------------------------------------------------------------- #
#  Clip / scene / track construction
# --------------------------------------------------------------------------- #

def _patch_clip(slot: ET.Element, track: AlsTrack, *, warp: bool,
                set_dir: str | None, slot_index: int) -> None:
    slot.set("Id", str(slot_index))
    clip = slot.find(".//AudioClip")
    clip.set("Id", str(slot_index + 1))    # unique within this ClipSlotList
    bpm = track.bpm or _FALLBACK_BPM       # post-init guarantees float > 0 or None
    dur = track.duration_sec or 0.0
    warped = bool(warp and track.bpm and dur > 0)
    beats = dur * bpm / 60.0 if warped else max(dur, 4.0)
    beats = round(beats, 6) if beats > 0 else 4.0

    _v(clip, "Name", track.display_name)
    if track.color is not None:
        _v(clip, "Color", int(track.color))
    _v(clip, "CurrentStart", 0)
    _v(clip, "CurrentEnd", beats)
    loop = clip.find("Loop")
    _v(loop, "LoopStart", 0)
    _v(loop, "LoopEnd", beats)
    _v(loop, "StartRelative", 0)
    _v(loop, "LoopOn", "false")          # DJ tracks play once, no loop
    _v(loop, "OutMarker", beats)
    _v(loop, "HiddenLoopStart", 0)
    _v(loop, "HiddenLoopEnd", beats)
    ts = clip.find("TimeSelection")
    _v(ts, "AnchorTime", 0)
    _v(ts, "OtherTime", beats)
    _v(clip, "IsWarped", "true" if warped else "false")
    if clip.find("WarpMode") is not None:
        _v(clip, "WarpMode", 4)          # Complex — right default for full tracks

    markers = clip.find("WarpMarkers")
    for m in list(markers):
        markers.remove(m)
    if warped:
        # Constant grid at the detected BPM: SecTime is SECONDS into the file.
        ET.SubElement(markers, "WarpMarker",
                      {"Id": "1", "SecTime": "0", "BeatTime": "0"})
        ET.SubElement(markers, "WarpMarker",
                      {"Id": "2", "SecTime": repr(dur), "BeatTime": repr(beats)})

    ref = clip.find("SampleRef")
    fr = ref.find("FileRef")
    abs_path = os.path.abspath(track.path)
    _v(fr, "Path", abs_path)
    rel = None
    if set_dir:
        try:
            rel = os.path.relpath(abs_path, set_dir)
        except ValueError:      # Windows: audio and set on different drives
            rel = None
    _v(fr, "RelativePathType", 1 if rel else 0)
    _v(fr, "RelativePath", rel if rel else abs_path)
    try:
        stat = os.stat(abs_path)
        _v(fr, "OriginalFileSize", stat.st_size)
        _v(ref, "LastModDate", int(stat.st_mtime))
    except OSError:
        _v(fr, "OriginalFileSize", 0)
        _v(ref, "LastModDate", 0)
    _v(fr, "OriginalCrc", 0)
    rate = track.sample_rate_hz or 44100
    _v(ref, "DefaultSampleRate", rate)
    _v(ref, "DefaultDuration", int(dur * rate) if dur else 0)
    _v(ref, "SamplesToAutoWarp", 0)      # our grid is authoritative — no auto-warp
    # Drop the donor set's browser/source context entirely.
    sc = ref.find("SourceContext")
    if sc is not None:
        for ch in list(sc):
            sc.remove(ch)


def _scene_label(i: int, track: AlsTrack) -> str:
    bits = [f"{i + 1:02d}"]
    if track.bpm:
        bits.append(f"{round(track.bpm)} BPM")
    if track.key:
        bits.append(str(track.key))
    return " · ".join(bits)


# --------------------------------------------------------------------------- #
#  Public API
# --------------------------------------------------------------------------- #

def build_live_set(entries: list[AlsTrack], *,
                   tempo: float | None = None,
                   warp: bool = True,
                   scene_tempo: bool = True,
                   deck_names: tuple[str, str] = ("TF Deck A", "TF Deck B"),
                   set_path: str | None = None) -> bytes:
    """Build a .als (gzipped XML) from playlist entries. Returns file bytes."""
    if not entries:
        raise ValueError("empty playlist — nothing to export")
    if tempo is not None:
        tempo = float(tempo)
        if not math.isfinite(tempo) or tempo <= 0:
            raise ValueError(f"tempo must be a positive number, got {tempo!r}")

    root = _load_template()
    liveset = root.find("LiveSet")
    tracks_el = liveset.find("Tracks")
    scenes_el = liveset.find("Scenes")
    set_dir = os.path.dirname(os.path.abspath(set_path)) if set_path else None

    # Detach the three templates.
    tmpl_track = tracks_el.find("AudioTrack")
    tracks_el.remove(tmpl_track)
    csl = tmpl_track.find("DeviceChain/MainSequencer/ClipSlotList")
    slots = csl.findall("ClipSlot")
    tmpl_filled = next(s for s in slots if s.find(".//AudioClip") is not None)
    tmpl_empty = next(s for s in slots if s.find(".//AudioClip") is None)
    for s in list(csl):
        csl.remove(s)
    tmpl_scene = scenes_el.find("Scene")
    scenes_el.remove(tmpl_scene)

    max_pointee = int(liveset.find("NextPointeeId").get("Value"))

    # Two deck tracks; entry i lives on deck i % 2, scene i.
    for deck in (0, 1):
        tr = copy.deepcopy(tmpl_track)
        tr.set("Id", str(100 + deck))
        name_el = tr.find("Name")
        _v(name_el, "EffectiveName", deck_names[deck])
        _v(name_el, "UserName", deck_names[deck])
        _v(name_el, "MemorizedFirstClipName", "")   # donor clip name lives here
        _v(tr, "Color", 12 if deck == 0 else 54)
        max_pointee = max(max_pointee,
                          _renumber_pointees(tr, (deck + 1) * ID_STRIDE))
        deck_csl = tr.find("DeviceChain/MainSequencer/ClipSlotList")
        for i, entry in enumerate(entries):
            if i % 2 == deck:
                slot = copy.deepcopy(tmpl_filled)
                _patch_clip(slot, entry, warp=warp,
                            set_dir=set_dir, slot_index=i)
            else:
                slot = copy.deepcopy(tmpl_empty)
                slot.set("Id", str(i))
            deck_csl.append(slot)
        # Live's writer keeps ReturnTracks LAST in <Tracks>; a deck appended
        # after them trips the loader's "more send knobs than return tracks"
        # corruption check. Insert decks before the returns.
        tracks_el.insert(deck, tr)

    # One scene per entry.
    for i, entry in enumerate(entries):
        sc = copy.deepcopy(tmpl_scene)
        sc.set("Id", str(i))
        _v(sc, "Name", _scene_label(i, entry))
        _v(sc, "Color", entry.color if entry.color is not None
           else _SCENE_COLORS[i % len(_SCENE_COLORS)])
        if scene_tempo and entry.bpm:
            _v(sc, "Tempo", round(float(entry.bpm), 2))
            _v(sc, "IsTempoEnabled", "true")
        scenes_el.append(sc)

    # Live keeps one ClipSlot per scene in EVERY sequencer — including each
    # track's FreezeSequencer and the MainTrack's — not just the session grid.
    # Resize every remaining donor-sized ClipSlotList to the scene count.
    n = len(entries)
    for csl_any in liveset.iter("ClipSlotList"):
        slots_any = csl_any.findall("ClipSlot")
        if len(slots_any) == n or not slots_any:
            continue                     # deck grids already match; empty = returns
        empty_tmpl = copy.deepcopy(slots_any[0])
        for s in list(csl_any):
            csl_any.remove(s)
        for i in range(n):
            s = copy.deepcopy(empty_tmpl)
            s.set("Id", str(i))
            csl_any.append(s)

    # Global tempo: explicit, else the first track's BPM.
    main_tempo = tempo if tempo is not None else next(
        (e.bpm for e in entries if e.bpm), _FALLBACK_BPM)
    _v(liveset.find("MainTrack").find(".//Tempo"), "Manual",
       round(float(main_tempo), 2))

    liveset.find("NextPointeeId").set("Value", str(max_pointee + 1))

    xml_bytes = b'<?xml version="1.0" encoding="UTF-8"?>\n' + ET.tostring(root)
    return gzip.compress(xml_bytes, mtime=0)


def write_als(out_path: str, entries: list[AlsTrack], **kwargs) -> str:
    """Build and write the set; relative sample paths are computed from out_path."""
    out_path = os.path.abspath(out_path)
    data = build_live_set(entries, set_path=out_path, **kwargs)
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "wb") as fh:
        fh.write(data)
    return out_path


# --------------------------------------------------------------------------- #
#  Tunefield bridge (standalone use + the model for the future Flask route)
# --------------------------------------------------------------------------- #

def _get_json(base: str, path: str, payload: dict | None = None):
    req = urllib.request.Request(
        base + path,
        data=json.dumps(payload).encode() if payload is not None else None,
        headers={"Content-Type": "application/json"} if payload is not None else {},
    )
    with urllib.request.urlopen(req, timeout=10) as res:
        return json.loads(res.read())


def fetch_playlist(base: str = "http://127.0.0.1:5050",
                   slug: str | None = None) -> tuple[str, list[AlsTrack]]:
    """Read a playlist (default: the active one) from the running Tunefield."""
    health = _get_json(base, "/system/health")
    root_dir = health["root"]
    pls = _get_json(base, "/playlists")
    slug = slug or pls.get("active_slug")
    if not slug:
        raise SystemExit("no active playlist — pass --playlist SLUG")
    pl = _get_json(base, f"/playlists/{slug}")
    ids = [t["track_id"] for t in pl.get("tracks", [])]
    if not ids:
        raise SystemExit(f"playlist '{slug}' is empty")
    # /tracks/resolve silently caps at 500 ids per request — chunk and merge.
    resolved: dict = {}
    for i in range(0, len(ids), _RESOLVE_CHUNK):
        chunk = ids[i:i + _RESOLVE_CHUNK]
        resolved.update(_get_json(base, "/tracks/resolve", {"ids": chunk})["found"])

    entries = []
    dropped = []
    for tid in ids:
        t = resolved.get(tid)
        if not t or not t.get("library_file"):
            dropped.append(tid)           # deleted or file-less entry
            continue
        lf = t["library_file"]
        entries.append(AlsTrack(
            path=lf if os.path.isabs(lf) else os.path.join(root_dir, lf),
            title=t.get("title"),
            artist=t.get("artist"),
            bpm=t.get("bpm"),
            key=t.get("key"),
            duration_sec=t.get("duration_sec"),
            sample_rate_hz=t.get("sample_rate_hz"),
        ))
    if dropped:
        print(f"warning: {len(dropped)} of {len(ids)} playlist tracks skipped "
              f"(deleted or no file): {', '.join(dropped[:5])}"
              f"{' …' if len(dropped) > 5 else ''}", file=sys.stderr)
    return pl.get("name") or slug, entries


def main() -> None:
    ap = argparse.ArgumentParser(description="Export a Tunefield playlist as a .als Live Set")
    ap.add_argument("--base", default="http://127.0.0.1:5050")
    ap.add_argument("--playlist", help="playlist slug (default: active playlist)")
    ap.add_argument("--out", help="output path (default: ./<playlist>.als)")
    ap.add_argument("--tempo", type=float, help="global tempo (default: first track's BPM)")
    ap.add_argument("--no-warp", action="store_true", help="leave clips unwarped")
    ap.add_argument("--no-scene-tempo", action="store_true",
                    help="do not write per-scene tempos")
    args = ap.parse_args()

    name, entries = fetch_playlist(args.base, args.playlist)
    safe_name = re.sub(r"[/:\\]", "-", name)
    out = args.out or f"./{safe_name}.als"
    path = write_als(out, entries, tempo=args.tempo, warp=not args.no_warp,
                     scene_tempo=not args.no_scene_tempo)
    print(f"wrote {path} — {len(entries)} tracks, "
          f"{'warped' if not args.no_warp else 'unwarped'}, "
          f"scene tempo {'on' if not args.no_scene_tempo else 'off'}")


if __name__ == "__main__":
    main()
